def dtc_printout_to_nice():
    ecuid = 2974#4655#3833 #2974
    ecuveid = 13746#1411 #30028 #13746
    f = "5712C402C403F40AF415A4A7F4BAA4C0A4C1F4C3A4C59562F5FFF015F019F02FC98B7173FA58"
    f = "5701229928"
