    f = "5717C402C403F40AF415A4A7F4BAB4BCA4C0A4C1F4C3A4C5A4C7A4C8A4C9A4CA9562F5FFF015F019F02FC98B71557173"
    k = bb.parse_dtc_response(ecuid,ecuveid,f)
    p = bb.get_dtc_printout(ecuid,ecuveid, k)
    for dtc in p:
        print(str(dtc) + " : " + p[dtc]["label"])
        for c in p[dtc]["chars"]:
            tit = str(c["title"])
            val = str(c["value"][0])
            print("  " + tit + " : " + val )


